'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');
const { Worker } = require('node:worker_threads');
const { performance } = require('node:perf_hooks');
const { simpleSieve, countInRange } = require('./sieve.js');

const N = 8_000_000;
const KNOWN_PI_N = 539_777; // oracle: pi(8e6)
const NUM_WORKERS = 4;

// ---- (a) main thread -------------------------------------------------------
function countSingleThread(n) {
  return countInRange(0, n + 1, simpleSieve(Math.floor(Math.sqrt(n))));
}

// ---- (b) range-partitioned worker pool -------------------------------------
// A pool of NUM_WORKERS persistent workers. The main thread computes base
// primes up to sqrt(N) once and partitions [0, N] into contiguous chunks;
// each worker sieves its chunk with those base primes.
class WorkerPool {
  constructor(size) {
    this.size = size;
    this.idle = [];
    this.queue = [];
    this.workers = Array.from({ length: size }, () => this.spawn());
  }

  spawn() {
    const w = new Worker(path.join(__dirname, 'worker.js'));
    w.unref();
    return w;
  }

  // Resolves with the worker's reply for one job { low, high, basePrimes }.
  run(job) {
    return new Promise((resolve, reject) => {
      const task = { job, resolve, reject };
      const free = this.idle.pop();
      if (free) this.execute(free, task);
      else this.queue.push(task);
    });
  }

  execute(worker, task) {
    worker.once('message', ({ count }) => {
      this.idle.push(worker);
      task.resolve(count);
      const next = this.queue.shift();
      if (next) this.execute(worker, next);
    });
    worker.once('error', (err) => task.reject(err));
    worker.postMessage(task.job);
  }
}

async function countWithWorkers(pool, n, numWorkers) {
  const basePrimes = simpleSieve(Math.floor(Math.sqrt(n)));
  const span = n + 1; // candidates are 0..n inclusive
  const chunk = Math.ceil(span / numWorkers);
  const jobs = [];
  for (let w = 0; w < numWorkers; w++) {
    const low = w * chunk;
    const high = Math.min(span, low + chunk);
    if (low < high) jobs.push(pool.run({ low, high, basePrimes }));
  }
  const counts = await Promise.all(jobs);
  return counts.reduce((a, b) => a + b, 0);
}

// Best-of-3 timing to dampen scheduler noise.
async function timeBestOf(fn, runs = 3) {
  let best = Infinity;
  for (let i = 0; i < runs; i++) {
    const t0 = performance.now();
    await fn();
    best = Math.min(best, performance.now() - t0);
  }
  return best;
}

// Pool is created once outside the timed region so we measure the parallel
// sieve itself, not thread startup cost.
const pool = new WorkerPool(NUM_WORKERS);

test('main-thread sieve matches pi(8e6) = 539777', () => {
  assert.equal(countSingleThread(N), KNOWN_PI_N);
});

test('4-worker partitioned sieve matches pi(8e6) = 539777', async () => {
  assert.equal(await countWithWorkers(pool, N, NUM_WORKERS), KNOWN_PI_N);
});

test('4-worker version is at least 1.3x faster than single-threaded', async () => {
  const singleMs = await timeBestOf(() => new Promise((res) => res(countSingleThread(N))));
  const workersMs = await timeBestOf(() => countWithWorkers(pool, N, NUM_WORKERS));

  console.log(`single-threaded : ${singleMs.toFixed(1)} ms`);
  console.log(`4 workers       : ${workersMs.toFixed(1)} ms`);
  console.log(`speedup         : ${(singleMs / workersMs).toFixed(2)}x`);

  assert.ok(
    singleMs / workersMs >= 1.3,
    `expected >= 1.3x speedup, got ${(singleMs / workersMs).toFixed(2)}x ` +
      `(single=${singleMs.toFixed(1)}ms, workers=${workersMs.toFixed(1)}ms)`
  );
});

